import { requireNativeViewManager } from "expo-modules-core";
import * as React from "react";

import type { HereMapsViewProps, HereMapsViewRef } from "./HereMaps.types";

// FIX: We use an intersection type (&) to tell TS this view takes your props PLUS a ref.
const NativeView: React.ComponentType<
  HereMapsViewProps & { ref?: React.ForwardedRef<HereMapsViewRef> }
> = requireNativeViewManager("HereMaps");

// forwardRef lets the parent component's mapRef actually touch the NativeView
const HereMapsView = React.forwardRef<HereMapsViewRef, HereMapsViewProps>(
  (props, ref) => {
    return <NativeView {...props} ref={ref} />;
  },
);

export default HereMapsView;

