32		onUseLocationDestination: () => void;
33		onClearOrigin: () => void;
34		onClearDestination: () => void;
35		onSwap: () => void;
36	};
37	
38	function RouteInputs({
39		active,
40		origin,
41		destination,
42		originValue,
43		destinationValue,
44		canSwap,
45		onSetQuery,
46		onFocusOrigin,
47		onFocusDestination,
48		onUseLocationOrigin,
49		onUseLocationDestination,
50		onClearOrigin,
51		onClearDestination,
52		onSwap,
53	}: RouteInputsProps) {
54		return (
55			<View className="flex-row items-stretch">
56				<View className="w-7 items-center justify-center py-5">
57					<View className="h-3 w-3 rounded-full border-[2.5px] border-muted-foreground" />
58					<View className="my-2 w-0.5 flex-1 rounded-full bg-border" />
59					<View className="h-3 w-3 rounded-[3px] bg-primary" />
60				</View>
61	
62				<View className="flex-1 overflow-hidden rounded-3xl border border-border bg-card">
63					<RoutePointField
64						value={originValue}
65						active={active === "origin"}
66						isCurrentLocation={origin.isCurrentLocation && active !== "origin"}
67						canUseLocation={active === "origin" && !origin.isCurrentLocation}
68						onChangeText={onSetQuery}
69						onFocus={onFocusOrigin}
70						onUseLocation={onUseLocationOrigin}
71						onClear={onClearOrigin}
72						placeholder="Choose start"
73					/>
74					<View className="ml-4 h-px bg-border" />
75					<RoutePointField
76						value={destinationValue}
77						active={active === "destination"}
78						isCurrentLocation={destination?.isCurrentLocation === true && active !== "destination"}
79						canUseLocation={active === "destination"}
80						onChangeText={onSetQuery}
81						onFocus={onFocusDestination}
82						onUseLocation={onUseLocationDestination}
83						onClear={onClearDestination}
84						placeholder="Where to?"
85					/>
86				</View>
87	
88				<View className="w-12 items-center justify-center">
89					<Pressable
90						onPress={onSwap}
91						disabled={!canSwap}
92						hitSlop={10}
93						className={canSwap ? "active:opacity-50" : "opacity-30"}
94					>
95						<View className="h-10 w-10 items-center justify-center rounded-full border border-border bg-background">
96							<ArrowUpDown size={17} className="text-foreground" strokeWidth={2.25} />
97						</View>
98					</Pressable>
99				</View>
100			</View>
101		);
102	}
103	
104	type StartButtonProps = {
105		isStarting: boolean;
106		onPress: () => void;
107	};
108	
