111			<Animated.View entering={FadeInUp.duration(220)}>
112				<Pressable onPress={onPress} disabled={isStarting} className="active:opacity-90">
113					<View className="flex-row items-center justify-center gap-2.5 rounded-2xl bg-primary py-4">
