120							{isStarting ? "Starting…" : "Start navigation"}
121						</Text>
122					</View>
123				</Pressable>
124			</Animated.View>
125		);
126	}
127	
128	// --- main export ---
129	
130	export function SheetSearch({ mapRef }: SheetSearchProps) {
131		const { snapTo } = useSheet();
132		const { phase } = useRouteState();
133		const {
134			query,
135			setQuery,
136			results,
137			isLoading,
138			hasSearched,
139			origin,
140			destination,
141			active,
