146			setFieldToCurrent,
147			clearField,
148			swap,
149			startNavigation,
150			stopNavigation,
151		} = useRouteSearch(mapRef);
152	
153		const handleStart = useCallback(async () => {
154			const ok = await startNavigation();
155			if (ok) snapTo(0);
156		}, [startNavigation, snapTo]);
157	
158		if (phase === "navigating") {
159			return (
