161					destination={destination?.label ?? "Destination"}
162					onEnd={stopNavigation}
163				/>
164			);
165		}
166	
167		const originValue =
168			active === "origin" ? query : origin.isCurrentLocation ? "Current location" : origin.label;
169	
170		const destinationValue = active === "destination" ? query : (destination?.label ?? "");
171		const canSwap = !!destination || !origin.isCurrentLocation;
172		const hasResults = results.length > 0;
173	
174		return (
