import { Search, X } from "lucide-react-native";
import { Pressable, Text, View } from "react-native";
import Animated, {
	useAnimatedStyle,
	useSharedValue,
	withSpring,
	withTiming,
	interpolate,
	Extrapolation,
} from "react-native-reanimated";
import { useEffect } from "react";

