import { useRouteState } from "@/features/navigation/route-context";
import { Check } from "lucide-react-native";
import { useEffect } from "react";
import { Text, View } from "react-native";
import Animated, {
	FadeIn,
	FadeOut,
	useAnimatedStyle,
	useSharedValue,
	withDelay,
	withSpring,
	withTiming,
} from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";

const DISMISS_MS = 3200;

export function ArrivalScreen() {
	const { phase, stopNavigation } = useRouteState();
	const insets = useSafeAreaInsets();

	const iconScale = useSharedValue(0.4);
	const iconOpacity = useSharedValue(0);
	const textOpacity = useSharedValue(0);
	const textY = useSharedValue(16);

	useEffect(() => {
		if (phase !== "arrived") return;
		iconScale.value = withSpring(1, { damping: 16, stiffness: 220 });
		iconOpacity.value = withTiming(1, { duration: 300 });
		textOpacity.value = withDelay(180, withTiming(1, { duration: 320 }));
		textY.value = withDelay(180, withSpring(0, { damping: 20, stiffness: 200 }));
		const t = setTimeout(() => stopNavigation(), DISMISS_MS);
		return () => clearTimeout(t);
	}, [phase, stopNavigation, iconScale, iconOpacity, textOpacity, textY]);

	const iconStyle = useAnimatedStyle(() => ({
		opacity: iconOpacity.value,
		transform: [{ scale: iconScale.value }],
	}));

	const textStyle = useAnimatedStyle(() => ({
		opacity: textOpacity.value,
		transform: [{ translateY: textY.value }],
	}));

	if (phase !== "arrived") return null;

	return (
		<Animated.View
			entering={FadeIn.duration(280)}
			exiting={FadeOut.duration(380)}
			className="absolute inset-0 items-center justify-center bg-background/92"
			style={{ paddingBottom: insets.bottom + 48 }}
		>
			<View className="items-center gap-6">
				{/* Success icon */}
				<Animated.View style={iconStyle}>
					<View className="h-24 w-24 items-center justify-center rounded-full bg-success/12">
						<View className="h-16 w-16 items-center justify-center rounded-full bg-success/20">
							<Check size={34} className="text-success" strokeWidth={2.75} />
						</View>
					</View>
				</Animated.View>

				{/* Copy */}
				<Animated.View style={textStyle} className="items-center gap-1.5">
					<Text className="text-[30px] font-bold tracking-tight text-foreground">
						You've arrived
					</Text>
					<Text className="text-[16px] text-muted-foreground">
						You've reached your destination
					</Text>
				</Animated.View>
			</View>
		</Animated.View>
	);
}

