import { Sheet, SheetExpanded, SheetPeek } from "@/components/ui/sheet";
import { useCurrentLocation } from "@/features/location/use-current-location";
import { ArrivalScreen } from "@/features/navigation/components/ArrivalScreen";
import { ManeuverBanner } from "@/features/navigation/components/ManeuverBanner";
import { SheetSearch } from "@/features/navigation/components/SheetSearch";
import { SheetSearchDecoy } from "@/features/navigation/components/SheetSearchDecoy";
import { RouteStateProvider, useRouteState } from "@/features/navigation/route-context";
import type { GuidanceProgressEvent, HereMapsViewRef, LatLng, ManeuverEvent } from "expo-here-maps";
import { HereMapsView } from "expo-here-maps";
import { Compass, LocateFixed, Navigation } from "lucide-react-native";
import { useCallback, useEffect, useRef, useState } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import Animated, {
	Easing,
	FadeIn,
	FadeInUp,
	FadeOut,
	FadeOutDown,
	interpolate,
	useAnimatedStyle,
	useSharedValue,
	withDelay,
	withRepeat,
	withTiming,
} from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";

// ─── Locating screen ─────────────────────────────────────────────────────────

function PulseRing({ delay = 0 }: { delay?: number }) {
	const progress = useSharedValue(0);

	useEffect(() => {
		progress.value = withDelay(
			delay,
			withRepeat(
				withTiming(1, { duration: 1800, easing: Easing.out(Easing.quad) }),
				-1,
			),
		);
	}, [delay, progress]);

	const style = useAnimatedStyle(() => ({
		opacity: interpolate(progress.value, [0, 0.4, 1], [0.45, 0.12, 0]),
		transform: [{ scale: interpolate(progress.value, [0, 1], [1, 2.6]) }],
	}));

	return (
		<Animated.View
			style={[style, { position: "absolute", width: 80, height: 80, borderRadius: 40 }]}
			className="bg-primary/20"
		/>
	);
}

function LocatingScreen() {
	const insets = useSafeAreaInsets();
	return (
		<View
			className="flex-1 items-center justify-center bg-background"
			style={{ paddingBottom: insets.bottom + 32 }}
		>
			<View className="h-48 w-48 items-center justify-center">
				<PulseRing delay={0} />
				<PulseRing delay={700} />
				<View className="h-20 w-20 items-center justify-center rounded-full bg-primary/10">
					<LocateFixed size={32} className="text-primary" strokeWidth={2} />
				</View>
			</View>
			<View className="items-center gap-1.5">
				<Text className="text-[19px] font-semibold tracking-tight text-foreground">
					Finding your location
				</Text>
				<Text className="text-[15px] text-muted-foreground">This just takes a moment</Text>
			</View>
		</View>
	);
}

// ─── Map controls (top-right column) ─────────────────────────────────────────

type MapControlsProps = {
	mapRef: React.RefObject<HereMapsViewRef | null>;
	location: LatLng | null;
	phase: string;
	isCameraFollowing: boolean;
	onReCenter: () => void;
};

function MapControls({ mapRef, location, phase, isCameraFollowing, onReCenter }: MapControlsProps) {
	const handleCompassPress = useCallback(() => {
		if (!location) return;
		mapRef.current?.setCameraPosition({
			lat: location.lat,
			lng: location.lng,
			bearing: 0,
			animated: true,
			distanceMeters: 800,
		});
	}, [mapRef, location]);

	return (
		<View className="gap-3">
			{/* Compass / North reset — always available, UK standard (like Google Maps) */}
			<Pressable onPress={handleCompassPress} hitSlop={8} className="active:opacity-60">
				<View className="h-12 w-12 items-center justify-center rounded-full bg-card shadow-md border border-border/50">
					<Compass size={21} className="text-foreground" strokeWidth={1.75} />
				</View>
			</Pressable>
		</View>
	);
}

// ─── Re-centre button ─────────────────────────────────────────────────────────
// Appears above the sheet when camera auto-follow is disengaged during navigation.
// Industry standard: Google Maps, Apple Maps, Waze all use this exact pattern.

function ReCentreButton({ onPress }: { onPress: () => void }) {
	return (
		<Animated.View
			entering={FadeInUp.duration(220).springify().damping(20)}
			exiting={FadeOutDown.duration(180)}
		>
			<Pressable onPress={onPress} className="active:opacity-70">
				<View className="flex-row items-center gap-2 rounded-full bg-primary px-5 py-3 shadow-lg">
					<Navigation size={15} color="#fff" fill="#fff" />
					<Text className="text-[14px] font-semibold text-primary-foreground">
						Re-centre
					</Text>
				</View>
			</Pressable>
		</Animated.View>
	);
}

// ─── Map screen ───────────────────────────────────────────────────────────────

function MapScreen() {
	const mapRef = useRef<HereMapsViewRef>(null);
	const location = useCurrentLocation();
	const [located, setLocated] = useState(false);
	const didCenter = useRef(false);
	const insets = useSafeAreaInsets();
	const { set, phase } = useRouteState();

	// Tracks whether DynamicCameraBehavior is active.
	// true  = map auto-follows GPS (normal guidance mode)
	// false = user panned away, show re-centre button
	const [isCameraFollowing, setIsCameraFollowing] = useState(true);

	// Reset following state whenever navigation stops
	useEffect(() => {
		if (phase !== "navigating") {
			setIsCameraFollowing(true);
		}
	}, [phase]);

	useEffect(() => {
		if (location && !didCenter.current) {
			didCenter.current = true;
			mapRef.current?.setCameraPosition({
				lat: location.lat,
				lng: location.lng,
				distanceMeters: 800,
			});
			setLocated(true);
		}
	}, [location]);

	const handleGuidanceProgress = useCallback(
		(e: { nativeEvent: GuidanceProgressEvent }) => {
			set({
				remainingMeters: e.nativeEvent.remainingMeters,
				etaSeconds: e.nativeEvent.etaSeconds,
			});
		},
		[set],
	);

	const handleManeuver = useCallback(
		(e: { nativeEvent: ManeuverEvent }) => {
			set({
				maneuverText: e.nativeEvent.text,
				maneuverAction: e.nativeEvent.action,
				maneuverDistanceMeters: e.nativeEvent.distanceMeters,
			});
		},
		[set],
	);

	const handleArrived = useCallback(() => {
		set({ phase: "arrived" });
	}, [set]);

	// Native fires this the moment the user touches the map during guidance
	const handleCameraDecouple = useCallback(() => {
		setIsCameraFollowing(false);
	}, []);

	// Re-centre: re-attach DynamicCameraBehavior and snap camera back to GPS
	const handleReCenter = useCallback(async () => {
		await mapRef.current?.setCameraFollowing(true);
		setIsCameraFollowing(true);
	}, []);

	const showReCentre = phase === "navigating" && !isCameraFollowing;
	// Sheet peek is 160px. Button sits 12px above it.
	const reCentreBottom = 160 + insets.bottom + 12;

	return (
		<View style={{ flex: 1 }}>
			<HereMapsView
				ref={mapRef}
				style={StyleSheet.absoluteFill}
				bearing={0}
				tilt={0}
				onGuidanceProgress={handleGuidanceProgress}
				onManeuver={handleManeuver}
				onArrived={handleArrived}
				onCameraDecouple={handleCameraDecouple}
			/>

			{/* Maneuver banner — top centre */}
			<ManeuverBanner />

			{/* Map controls — top right */}
			<View
				style={{
					position: "absolute",
					top: insets.top + 16,
					right: 16,
					zIndex: 40,
				}}
			>
				<MapControls
					mapRef={mapRef}
					location={location}
					phase={phase}
					isCameraFollowing={isCameraFollowing}
					onReCenter={handleReCenter}
				/>
			</View>

			{/* Re-centre button — centred above sheet, only when camera is decoupled */}
			{showReCentre ? (
				<View
					style={{
						position: "absolute",
						bottom: reCentreBottom,
						left: 0,
						right: 0,
						zIndex: 40,
						alignItems: "center",
					}}
				>
					<ReCentreButton onPress={handleReCenter} />
				</View>
			) : null}

			<Sheet snapPoints={["peek", "half", "full"]}>
				<SheetPeek>
					<SheetSearchDecoy />
				</SheetPeek>
				<SheetExpanded>
					<SheetSearch mapRef={mapRef} />
				</SheetExpanded>
			</Sheet>

			<ArrivalScreen />

			{!located ? (
				<Animated.View exiting={FadeOut.duration(400)} style={StyleSheet.absoluteFill}>
					<LocatingScreen />
				</Animated.View>
			) : null}
		</View>
	);
}

// ─── Root ─────────────────────────────────────────────────────────────────────

export default function Home() {
	return (
		<RouteStateProvider>
			<MapScreen />
		</RouteStateProvider>
	);
}

import type { StyleProp, ViewStyle } from 'react-native';
import type { TransportMode } from './HereMapsConstants';

export type { TransportMode } from './HereMapsConstants';

// --- Core geometry types ---

export type LatLng = {
  lat: number;
  lng: number;
};

export type MapCenter = LatLng & {
  animated?: boolean;
};

export type CameraPosition = LatLng & {
  animated?: boolean;
  bearing?: number;
  tilt?: number;
  distanceMeters?: number;
};

// --- Search ---

export type GeoJsonFeature = {
  type: 'Feature';
  geometry: { type: 'Point'; coordinates: [number, number] } | null;
  properties: {
    title: string;
    subtitle: string;
    placeId: string;
    resolved: boolean;
  };
};

export type GeoJsonFeatureCollection = {
  type: 'FeatureCollection';
  features: GeoJsonFeature[];
};

// --- Routing ---

export type RouteSummary = {
  distanceMeters: number;
  durationSeconds: number;
};

export type CompareRouteResult = RouteSummary & {
  mode: TransportMode;
};

// --- Events ---

export type MapErrorEvent = {
  code: string;
  message: string;
};

export type GuidanceProgressEvent = {
  remainingMeters: number;
  etaSeconds: number;
};

export type ManeuverEvent = {
  text: string;
  action: string;
  distanceMeters: number;
};

export type OffRouteEvent = {
  distanceFromRoute: number;
};

export type ArrivedEvent = Record<string, never>;

export type NavigableLocationEvent = {
  streetName?: string;
  speedLimit?: number;
};

// --- View props ---

export type HereMapsViewProps = {
  center?: MapCenter;
  bearing?: number;
  tilt?: number;
  style?: StyleProp<ViewStyle>;

  // Error
  onMapError?: (event: { nativeEvent: MapErrorEvent }) => void;

  // Guidance events
  onGuidanceProgress?: (event: { nativeEvent: GuidanceProgressEvent }) => void;
  onManeuver?: (event: { nativeEvent: ManeuverEvent }) => void;
  onOffRoute?: (event: { nativeEvent: OffRouteEvent }) => void;
  onArrived?: (event: { nativeEvent: ArrivedEvent }) => void;
  onNavigableLocation?: (event: { nativeEvent: NavigableLocationEvent }) => void;

  // Fired when the user touches the map during navigation, decoupling DynamicCameraBehavior.
  // Show a re-centre button and call setCameraFollowing(true) when pressed.
  onCameraDecouple?: (event: { nativeEvent: Record<string, never> }) => void;
};

// --- Imperative ref ---

export type HereMapsViewRef = {
  // Map controls
  setMapScheme(scheme: string): Promise<void>;
  enableFeatures(features: string[]): Promise<void>;
  disableFeatures(features: string[]): Promise<void>;
  setCameraPosition(position: CameraPosition): Promise<void>;

  // Search
  suggestPlaces(query: string, near: LatLng): Promise<GeoJsonFeatureCollection>;
  resolvePlace(placeId: string): Promise<LatLng>;

  // Route (visual only, no guidance)
  showRoute(from: LatLng, to: LatLng, mode?: TransportMode): Promise<RouteSummary>;
  clearRoute(): void;

  // Multi-modal comparison (no drawing)
  compareRoutes(from: LatLng, to: LatLng, modes: TransportMode[]): Promise<CompareRouteResult[]>;

  // Turn-by-turn guidance
  startGuidance(from: LatLng, to: LatLng, mode?: TransportMode): Promise<RouteSummary>;
  stopGuidance(): void;

  // Camera follow — enable/disable DynamicCameraBehavior during active guidance.
  // Call setCameraFollowing(false) is automatic (fired via onCameraDecouple when user pans).
  // Call setCameraFollowing(true) from your re-centre button to snap back.
  setCameraFollowing(enabled: boolean): Promise<void>;

  // User location
  updateUserLocation(lat: number, lng: number, bearing?: number | null): void;
};

package expo.modules.heremaps

import com.here.sdk.core.GeoCoordinates
import expo.modules.kotlin.exception.CodedException
import expo.modules.kotlin.functions.Coroutine
import expo.modules.kotlin.modules.Module
import expo.modules.kotlin.modules.ModuleDefinition
import expo.modules.kotlin.records.Field
import expo.modules.kotlin.records.Record
import expo.modules.kotlin.types.Enumerable

class MapCenter : Record {
    @Field val lat: Double = 0.0
    @Field val lng: Double = 0.0
    @Field val animated: Boolean = false
}

class CameraPosition : Record {
    @Field val lat: Double = 0.0
    @Field val lng: Double = 0.0
    @Field val animated: Boolean = false
    @Field val bearing: Double? = null
    @Field val tilt: Double? = null
    @Field val distanceMeters: Double? = null
}

class LatLng : Record {
    @Field val lat: Double = 0.0
    @Field val lng: Double = 0.0
}

class SearchArea : Record {
    @Field val lat: Double = 0.0
    @Field val lng: Double = 0.0
}

enum class TransportMode(val value: String) : Enumerable {
    car("car"),
    truck("truck"),
    pedestrian("pedestrian"),
    bicycle("bicycle"),
    scooter("scooter"),
    taxi("taxi"),
    bus("bus")
}

class HereMapsModule : Module() {
    override fun definition() = ModuleDefinition {
        Name("HereMaps")

        View(HereMapsView::class) {
            Events(
                "onMapError",
                "onGuidanceProgress",
                "onManeuver",
                "onOffRoute",
                "onArrived",
                "onNavigableLocation",
                "onCameraDecouple"
            )

            Prop("center") { view: HereMapsView, center: MapCenter ->
                view.setMapCenter(center.lat, center.lng, center.animated)
            }
            Prop("bearing") { view: HereMapsView, bearing: Double ->
                view.setBearing(bearing)
            }
            Prop("tilt") { view: HereMapsView, tilt: Double ->
                view.setTilt(tilt)
            }

            AsyncFunction("setMapScheme") { view: HereMapsView, scheme: String ->
                when (val r = view.controls.setScheme(scheme)) {
                    is MapResult.Ok -> {}
                    is MapResult.Err -> throw CodedException(r.code, r.message, null)
                }
            }
            AsyncFunction("enableFeatures") { view: HereMapsView, features: List<String> ->
                when (val r = view.controls.enableFeatures(features)) {
                    is MapResult.Ok -> {}
                    is MapResult.Err -> throw CodedException(r.code, r.message, null)
                }
            }
            AsyncFunction("disableFeatures") { view: HereMapsView, features: List<String> ->
                when (val r = view.controls.disableFeatures(features)) {
                    is MapResult.Ok -> {}
                    is MapResult.Err -> throw CodedException(r.code, r.message, null)
                }
            }
            AsyncFunction("setCameraPosition") { view: HereMapsView, pos: CameraPosition ->
                view.setMapCenter(pos.lat, pos.lng, pos.animated, pos.distanceMeters)
                pos.bearing?.let { view.setBearing(it) }
                pos.tilt?.let { view.setTilt(it) }
            }

            AsyncFunction("suggestPlaces") Coroutine { view: HereMapsView, query: String, near: SearchArea ->
                val nearCoords = GeoCoordinates(near.lat, near.lng)
                when (val result = view.searchManager.suggest(query, nearCoords)) {
                    is HereResult.Ok -> result.value
                    is HereResult.Err -> throw CodedException(result.code, result.message, result.cause)
                }
            }

            AsyncFunction("resolvePlace") Coroutine { view: HereMapsView, placeId: String ->
                when (val result = view.searchManager.resolvePlace(placeId)) {
                    is HereResult.Ok -> result.value
                    is HereResult.Err -> throw CodedException(result.code, result.message, result.cause)
                }
            }

            AsyncFunction("showRoute") Coroutine { view: HereMapsView, from: LatLng, to: LatLng, mode: TransportMode? ->
                val transportMode = when (mode) {
                    TransportMode.car -> HereTransportMode.CAR
                    TransportMode.truck -> HereTransportMode.TRUCK
                    TransportMode.pedestrian -> HereTransportMode.PEDESTRIAN
                    TransportMode.bicycle -> HereTransportMode.BICYCLE
                    TransportMode.scooter -> HereTransportMode.SCOOTER
                    TransportMode.taxi -> HereTransportMode.TAXI
                    TransportMode.bus -> HereTransportMode.BUS
                    null -> HereTransportMode.CAR
                }
                val fromCoords = GeoCoordinates(from.lat, from.lng)
                val toCoords = GeoCoordinates(to.lat, to.lng)
                when (val result = view.routeManager.showRoute(fromCoords, toCoords, transportMode)) {
                    is HereResult.Ok -> result.value
                    is HereResult.Err -> throw CodedException(result.code, result.message, result.cause)
                }
            }

            AsyncFunction("clearRoute") { view: HereMapsView ->
                view.routeManager.clearRoute()
            }

            AsyncFunction("compareRoutes") Coroutine { view: HereMapsView, from: LatLng, to: LatLng, modes: List<TransportMode> ->
                val hereModes = modes.map { mode ->
                    when (mode) {
                        TransportMode.car -> HereTransportMode.CAR
                        TransportMode.truck -> HereTransportMode.TRUCK
                        TransportMode.pedestrian -> HereTransportMode.PEDESTRIAN
                        TransportMode.bicycle -> HereTransportMode.BICYCLE
                        TransportMode.scooter -> HereTransportMode.SCOOTER
                        TransportMode.taxi -> HereTransportMode.TAXI
                        TransportMode.bus -> HereTransportMode.BUS
                    }
                }
                val fromCoords = GeoCoordinates(from.lat, from.lng)
                val toCoords = GeoCoordinates(to.lat, to.lng)
                when (val result = view.routeManager.compareRoutes(fromCoords, toCoords, hereModes)) {
                    is HereResult.Ok -> result.value
                    is HereResult.Err -> throw CodedException(result.code, result.message, result.cause)
                }
            }

            AsyncFunction("startGuidance") Coroutine { view: HereMapsView, from: LatLng, to: LatLng, mode: TransportMode? ->
                val transportMode = when (mode) {
                    TransportMode.car -> HereTransportMode.CAR
                    TransportMode.truck -> HereTransportMode.TRUCK
                    TransportMode.pedestrian -> HereTransportMode.PEDESTRIAN
                    TransportMode.bicycle -> HereTransportMode.BICYCLE
                    TransportMode.scooter -> HereTransportMode.SCOOTER
                    TransportMode.taxi -> HereTransportMode.TAXI
                    TransportMode.bus -> HereTransportMode.BUS
                    null -> HereTransportMode.CAR
                }
                val fromCoords = GeoCoordinates(from.lat, from.lng)
                val toCoords = GeoCoordinates(to.lat, to.lng)
                when (val result = view.routeManager.calculateRoute(fromCoords, toCoords, transportMode)) {
                    is HereResult.Ok -> {
                        view.routeManager.clearRoute()
                        view.guidanceManager.startGuidance(result.value)
                        routeSummary(result.value)
                    }
                    is HereResult.Err -> throw CodedException(result.code, result.message, result.cause)
                }
            }

            AsyncFunction("stopGuidance") { view: HereMapsView ->
                view.guidanceManager.stopGuidance()
            }

            AsyncFunction("setCameraFollowing") { view: HereMapsView, enabled: Boolean ->
                view.guidanceManager.setCameraFollowing(enabled)
            }

            AsyncFunction("updateUserLocation") { view: HereMapsView, lat: Double, lng: Double, bearing: Double? ->
                view.updateUserLocation(lat, lng, bearing)
            }

            OnViewDestroys { view: HereMapsView ->
                view.onDestroy()
            }
        }
    }
}

package expo.modules.heremaps

import android.content.Context
