						alignItems: "center",
					}}
				>
					<ReCentreButton onPress={handleReCenter} />
				</View>
			) : null}

			<Sheet snapPoints={["peek", "half", "full"]}>
				<SheetPeek>
					<SheetSearchDecoy />
				</SheetPeek>
				<SheetExpanded>
					<SheetSearch mapRef={mapRef} />
				</SheetExpanded>
			</Sheet>

			<ArrivalScreen />

			{!located ? (
				<Animated.View exiting={FadeOut.duration(400)} style={StyleSheet.absoluteFill}>
					<LocatingScreen />
				</Animated.View>
			) : null}
		</View>
	);
}

// ─── Root ─────────────────────────────────────────────────────────────────────

export default function Home() {
	return (
		<RouteStateProvider>
			<MapScreen />
		</RouteStateProvider>
	);
}

