import { useSheet } from "@/components/ui/sheet";
import { useRouteState } from "@/features/navigation/route-context";
import { formatManeuverDistance, formatDuration, formatEta } from "@/features/navigation/lib/format-route";
import type { ManeuverItem } from "expo-here-maps";
import {
	ArrowLeft,
	ArrowRight,
	ArrowUp,
	ChevronsLeft,
	ChevronsRight,
	MapPin,
	RefreshCw,
	RotateCcw,
	Search,
	X,
} from "lucide-react-native";
import { useEffect } from "react";
import { Pressable, Text, View } from "react-native";
import Animated, {
	Extrapolation,
	interpolate,
	useAnimatedStyle,
	useSharedValue,
	withTiming,
} from "react-native-reanimated";

// ─── Maneuver action → icon ───────────────────────────────────────────────────

type IconComponent = React.ComponentType<{ size: number; strokeWidth: number; className: string }>;

function maneuverIcon(action: string): IconComponent {
	const a = action.toUpperCase();
	if (a.includes("LEFT")) return ArrowLeft;
	if (a.includes("RIGHT")) return ArrowRight;
	if (a === "U_TURN" || a === "UTURN") return RotateCcw;
	if (a.includes("ROUNDABOUT")) return RefreshCw;
	if (a === "ARRIVE") return MapPin;
	if (a === "KEEP_LEFT") return ChevronsLeft;
	if (a === "KEEP_RIGHT") return ChevronsRight;
	return ArrowUp;
}

// ─── Single maneuver row ──────────────────────────────────────────────────────

function ManeuverRow({ item, isFirst }: { item: ManeuverItem; isFirst: boolean }) {
	const Icon = maneuverIcon(item.action);
	const distance = formatManeuverDistance(item.distanceMeters);

	return (
		<View className="flex-row items-center gap-3 py-2.5">
			{/* Direction icon in a small muted circle */}
			<View
				className={`h-8 w-8 items-center justify-center rounded-full ${
					isFirst ? "bg-primary/10" : "bg-muted"
				}`}
			>
				<Icon
					size={15}
					strokeWidth={2.5}
					className={isFirst ? "text-primary" : "text-muted-foreground"}
				/>
			</View>

			{/* Street name */}
			<Text
				className={`flex-1 text-[14px] leading-tight ${
					isFirst ? "font-semibold text-foreground" : "font-normal text-muted-foreground"
				}`}
				numberOfLines={1}
			>
				{item.text || "Continue"}
			</Text>

			{/* Distance — right-aligned */}
			<Text
				className={`text-[13px] tabular-nums ${
					isFirst ? "font-semibold text-foreground" : "text-muted-foreground"
				}`}
			>
				{distance}
			</Text>
		</View>
	);
}

// ─── Nav peek ─────────────────────────────────────────────────────────────────

function NavPeek() {
	const { etaSeconds, remainingMeters, totalMeters, maneuverList, stopNavigation } = useRouteState();

	const progress =
		totalMeters != null && remainingMeters != null
			? Math.max(0, Math.min(1, 1 - remainingMeters / totalMeters))
			: 0;

	const progressAnim = useSharedValue(progress);

	useEffect(() => {
		progressAnim.value = withTiming(progress, { duration: 1000 });
	}, [progress, progressAnim]);

	const barStyle = useAnimatedStyle(() => ({
		width: `${interpolate(progressAnim.value, [0, 1], [0, 100], Extrapolation.CLAMP)}%`,
	}));

	// Show at most 5 upcoming maneuvers
	const upcoming = maneuverList.slice(0, 5);

	return (
		<View className="gap-3">
			{/* Progress track */}
			<View className="h-[3px] w-full overflow-hidden rounded-full bg-muted">
				<Animated.View style={barStyle} className="h-full rounded-full bg-primary" />
			</View>

			{/* ETA row + stop button */}
			<View className="flex-row items-end justify-between">
				<View className="gap-0.5">
					<Text className="text-[32px] font-bold leading-none tracking-tight text-foreground">
						{etaSeconds != null ? formatDuration(etaSeconds) : "—"}
					</Text>
					<Text className="text-[13px] text-muted-foreground">
						{[
							remainingMeters != null ? formatManeuverDistance(remainingMeters) : null,
							etaSeconds != null ? `Arrive ${formatEta(etaSeconds)}` : null,
						]
							.filter(Boolean)
							.join("  ·  ")}
					</Text>
				</View>

				<Pressable onPress={stopNavigation} hitSlop={14} className="active:opacity-60">
					<View className="h-11 w-11 items-center justify-center rounded-full bg-destructive/10">
						<X size={18} className="text-destructive" strokeWidth={2.5} />
					</View>
				</Pressable>
			</View>

			{/* Maneuver list — only shown when we have data */}
			{upcoming.length > 0 ? (
				<View>
					{/* Hairline separator */}
					<View className="h-px bg-border mb-1" />
					{upcoming.map((item, i) => (
						<ManeuverRow key={`${item.action}-${item.distanceMeters}-${i}`} item={item} isFirst={i === 0} />
					))}
				</View>
			) : null}
		</View>
	);
}

// ─── Idle pill ─────────────────────────────────────────────────────────────────

export function SheetSearchDecoy() {
	const { expand } = useSheet();
	const { phase } = useRouteState();

	if (phase === "navigating") {
		return <NavPeek />;
	}

	return (
		<Pressable onPress={expand} className="active:opacity-80">
			<View className="flex-row items-center gap-3 rounded-2xl bg-card px-4 py-4 shadow-md border border-border/50">
				<View className="h-8 w-8 items-center justify-center rounded-full bg-primary/10">
					<Search size={17} className="text-primary" strokeWidth={2.5} />
				</View>
				<Text className="flex-1 text-[17px] font-medium tracking-tight text-foreground">
					Where to?
				</Text>
				<View className="h-2 w-2 rounded-full bg-success" />
			</View>
		</Pressable>
	);
}

